cd /private/tmp/claude-501/-Users-suhas-sde/4c7c42ac-1b35-48c9-9855-f12e12882fae/scratchpad && cat >> lab_seed.sql <<'EOF'

-- Lab kit: order-insensitive and order-sensitive result fingerprints (row count : 8 hex chars of md5)
CREATE FUNCTION chk(q text) RETURNS text LANGUAGE plpgsql AS $f$
DECLARE r text;
BEGIN
  EXECUTE format('SELECT count(*) || '':'' || left(md5(coalesce(string_agg(t::text, ''|'' ORDER BY t::text), '''')), 8) FROM (%s) t', q) INTO r;
  RETURN r;
END $f$;

CREATE FUNCTION chk_o(q text) RETURNS text LANGUAGE plpgsql AS $f$
DECLARE r text;
BEGIN
  EXECUTE format('SELECT count(*) || '':'' || left(md5(coalesce(string_agg(t::text, ''|'' ORDER BY rn), '''')), 8) FROM (SELECT row_number() OVER () AS rn, x.* FROM (%s) x) t', q) INTO r;
  RETURN r;
END $f$;

CREATE SCHEMA IF NOT EXISTS work;
EOF
export PGHOST=localhost PGPORT=54329 PGUSER=lab PGDATABASE=labdb
psql -q -v ON_ERROR_STOP=1 -c "ALTER DATABASE labdb SET timezone TO 'UTC'" -f lab_schema.sql -f lab_seed.sql 2>&1 | tail -3
psql -Atc "select lab.chk('select 1 a, 2 b')" -c "select lab.chk_o('select generate_series(1,3) order by 1 desc')" -c "select count(*) from lab.stg_import"
which python3 pgbench

