from itertools import combinations, permutations
import math
def closure(X,F):
    X=set(X); ch=True
    while ch:
        ch=False
        for l,r in F:
            if set(l)<=X and not set(r)<=X: X|=set(r); ch=True
    return X
def keys(attrs,F):
    ks=[]
    for n in range(1,len(attrs)+1):
        for c in combinations(attrs,n):
            if closure(c,F)==set(attrs) and not any(set(k)<=set(c) for k in ks): ks.append(c)
    return ks
A="ABCDE"; F=[("A","B"),("BC","D"),("D","E"),("E","A")]
print("TD1 (A)+",sorted(closure("A",F)),"(BC)+",sorted(closure("BC",F)),"keys",keys(A,F))
# TD3
F3=[("AB","C"),("C","B")]; print("TD3 keys",keys("ABC",F3),"C+",closure("C",F3))
# canonical cover / minimal cover for a set
F4=[("A","BC"),("B","C"),("A","B"),("AB","C")]
print("TD-cover: closure check A+",closure("A",F4))
# serializability
def prec(s):
    ops=[(t,a,x) for (t,a,x) in s]
    E=set()
    for i,(t1,a1,x1) in enumerate(ops):
        for (t2,a2,x2) in ops[i+1:]:
            if t1!=t2 and x1==x2 and (a1=='w' or a2=='w'): E.add((t1,t2))
    return E
def cyc(E):
    nodes={n for e in E for n in e}
    for p in permutations(nodes):
        pass
    # simple DFS
    g={n:[b for a,b in E if a==n] for n in nodes}
    def dfs(n,st,seen):
        if n in st: return True
        if n in seen: return False
        seen.add(n); st.add(n)
        r=any(dfs(m,st,seen) for m in g[n]); st.discard(n); return r
    return any(dfs(n,set(),set()) for n in nodes)
S=[ [(1,'r','x'),(2,'w','x'),(1,'w','x')],
    [(1,'r','x'),(1,'w','x'),(2,'r','x'),(2,'w','x')],
    [(1,'r','x'),(2,'r','x'),(2,'w','x'),(1,'w','x')],
    [(1,'r','x'),(2,'r','y'),(1,'w','y'),(2,'w','x')],
    [(1,'r','x'),(2,'w','x'),(2,'w','y'),(1,'r','y')],
