            "counts": dict(sorted(counts.items())), "labels_by_name": counts_by_label, "items": out}


def owner_id(lines, i):
    """nearest preceding heading that leads with an exercise ID"""
    for j in range(i, -1, -1):
        m = re.match(r"^#{2,6}\s+(\S+)", lines[j])
        if m:
            return m.group(1)
